          // lifecycle (`onResponse`, `onDispose`) unfinished and the source alive with
          // its resources (file descriptors, sockets) held. Destroy it to settle both.
          const onResClose = () => {
            stream.destroy();
            resolve(kHandled);
          };
          const settle = (cb: () => void) => {
            res.removeListener("close", onResClose);
            cb();
          };
          const onStreamClose = () => settle(() => resolve(kHandled));
          stream.once("close", onStreamClose);
          stream.once("error", (error: any) =>
            settle(() => {
              // The source emits "close" right after "error": settle once the error hook is done
              stream.removeListener("close", onStreamClose);
              console.error("[h3] Stream error in Node.js handler", {
                cause: error,
              });
              // We cannot alter the outgoing response at this point, so the error hook
              // is only called to report the error (its return value is ignored)
              const config = event.app?.config;
              const onError = config?.onError;
              if (!onError) {
                return reject(kHandled);
              }
              Promise.resolve()
                .then(() => onError(new HTTPError({ cause: error, unhandled: true }), event))
                .catch((hookError) => {
                  if (!config.silent) console.error(hookError);
                })
                .finally(() => reject(kHandled));
            }),
          );
          // The client may have disconnected already — "close" was emitted before this
          // listener could be attached and would never fire.
          if (res.closed || res.destroyed) {
            onResClose();
          } else {
            res.once("close", onResClose);
          }
        }),
      );
    });
    try {
      if (isMiddleware) {
        Promise.resolve(
          handler(req, res, (error) =>
            error ? reject(new HTTPError({ cause: error, unhandled: true })) : resolve(void 0),
          ),
        ).catch((error) => reject(new HTTPError({ cause: error, unhandled: true })));
      } else {
        return Promise.resolve((handler as NodeHandler)(req, res))
          .then(() => resolve(kHandled))
          .catch((error) => reject(new HTTPError({ cause: error, unhandled: true })));
      }
    } catch (error: unknown) {
      reject(new HTTPError({ cause: error, unhandled: true }));
    }
  });
