4	import { describeMatrix } from "./_setup.ts";
5	
6	describeMatrix("errors", (t, { it, expect, describe }) => {
7	  const consoleMock = ((globalThis.console.error as any) = vi.fn());
8	
9	  describe("error response bodies", () => {
10	    for (const withOnError of [false, true]) {
11	      const hook = withOnError ? "with onError" : "without onError";
12	
13	      it(`omits the body for a missing HEAD route ${hook}`, async () => {
14	        if (!withOnError) t.app.config.onError = undefined;
15	        const res = await t.fetch("/missing", { method: "HEAD" });
16	        expect(res.status).toBe(404);
17	        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
18	        expect(res.headers.get("content-length")).toBeNull();
19	        expect(await res.text()).toBe("");
20	        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
21	        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
22	      });
23	
24	      for (const asyncHandler of [false, true]) {
25	        for (const method of ["GET", "HEAD"]) {
26	          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
27	            if (!withOnError) t.app.config.onError = undefined;
28	            const handler = (event: H3Event) => {
29	              event.res.headers.set("x-success", "success");
30	              event.res.errHeaders.set("x-error", "prepared");
31	              event.res.errHeaders.append("set-cookie", "prepared=1");
32	              throw new HTTPError({
33	                status: 422,
34	                statusText: "Unprocessable",
35	                data: { test: 123 },
36	                headers: { "x-error-own": "own", "set-cookie": "error=1" },
37	              });
38	            };
39	            t.app.use(asyncHandler ? async (event) => handler(event) : handler);
40	
41	            const res = await t.fetch("/", { method });
42	            expect(res.status).toBe(422);
43	            expect(res.statusText).toBe("Unprocessable");
44	            expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
45	            expect(res.headers.get("x-error")).toBe("prepared");
46	            expect(res.headers.get("x-error-own")).toBe("own");
47	            expect(res.headers.get("x-success")).toBeNull();
48	            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
49	            if (method === "HEAD") {
50	              expect(res.headers.get("content-length")).toBeNull();
51	              expect(await res.text()).toBe("");
52	            } else {
53	              expect(await res.json()).toMatchObject({
54	                status: 422,
55	                statusText: "Unprocessable",
56	                data: { test: 123 },
57	              });
58	            }
59	            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
60	            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
61	          });
62	        }
63	      }
64	    }
65	  });
66	
67	  it("throw HTTPError", async () => {
68	    t.app.use(() => {
69	      throw new HTTPError({
70	        statusText: "Unprocessable",
71	        status: 422,
72	        data: { test: 123 },
73	        body: { topLevel: "works" },
74	      });
75	    });
76	    const result = await t.fetch("/");
77	    expect(result.status).toBe(422);
78	    expect(result.statusText).toBe("Unprocessable");
79	    expect(await result.json()).toMatchObject({
80	      status: 422,
81	      statusText: "Unprocessable",
82	      message: "Unprocessable",
83	      data: { test: 123 },
84	      topLevel: "works",
85	    });
86	  });
87	
