89	    t.app.use(() => {
90	      return new HTTPError({
91	        statusText: "Unprocessable",
92	        status: 422,
93	        data: { test: 123 },
94	      });
95	    });
96	    const result = await t.fetch("/");
97	    expect(result.status).toBe(422);
98	    expect(result.statusText).toBe("Unprocessable");
99	    expect(await result.json()).toMatchObject({
100	      status: 422,
101	      statusText: "Unprocessable",
102	      message: "Unprocessable",
103	      data: { test: 123 },
104	    });
105	  });
106	
107	  it("unandled errors", async () => {
108	    t.app.use("/api/test", () => {
109	      // @ts-expect-error
110	      foo.bar = 123;
111	    });
112	    const result = await t.fetch("/api/test");
113	
114	    expect(t.errors[0].message).toMatch("foo is not defined");
